CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS; CREATE SCHEMA auth; CREATE TABLE auth.users(id uuid PRIMARY KEY); GRANT USAGE ON SCHEMA auth TO authenticated,anon; CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE public.app_users("id" text NOT NULL,"email" text NOT NULL,"first_name" text NOT NULL DEFAULT ''::text,"last_name" text NOT NULL DEFAULT ''::text,"full_name" text NOT NULL DEFAULT ''::text,"password" text,"role" text NOT NULL DEFAULT 'accountant'::text,"role_title" text NOT NULL DEFAULT ''::text,"status" text NOT NULL DEFAULT 'active'::text,"permissions" jsonb NOT NULL DEFAULT '{}'::jsonb,"avatar_color" text,"last_login" text,"phone" text,"notes" text,"created_at" text NOT NULL DEFAULT ''::text,"db_created_at" timestamptz NOT NULL DEFAULT now(),"db_updated_at" timestamptz NOT NULL DEFAULT now(),UNIQUE (email),PRIMARY KEY (id),CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'pending'::text]))));
CREATE TABLE public.bank_accounts("id" text NOT NULL,"bank_name" text NOT NULL DEFAULT ''::text,"account_number" text NOT NULL DEFAULT ''::text,"card_number" text,"shaba_number" text NOT NULL DEFAULT ''::text,"branch_name" text,"account_holder" text NOT NULL DEFAULT ''::text,"account_type" text NOT NULL DEFAULT 'current'::text,"balance" bigint NOT NULL DEFAULT 0,"currency" text DEFAULT 'rial'::text,"is_active" boolean NOT NULL DEFAULT true,"pos_terminal_id" text,"internet_banking_id" text,"color_theme" text,"notes" text,"created_at" text NOT NULL DEFAULT ''::text,"updated_at" text,"db_created_at" timestamptz NOT NULL DEFAULT now(),"db_updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (id));
CREATE TABLE public.employees("id" text NOT NULL,"name" text NOT NULL DEFAULT ''::text,"role" text NOT NULL DEFAULT ''::text,"start_date" text NOT NULL DEFAULT ''::text,"end_date" text,"status" text NOT NULL DEFAULT 'active'::text,"base_salary" bigint NOT NULL DEFAULT 0,"has_insurance" boolean NOT NULL DEFAULT false,"insurance_number" text,"iban" text,"national_id" text,"phone" text,"notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (id),CHECK ((status = ANY (ARRAY['active'::text, 'resigned'::text, 'probation'::text]))));
CREATE TABLE public.fiscal_years("year" integer NOT NULL,"title" text NOT NULL DEFAULT ''::text,"start_date" text NOT NULL DEFAULT ''::text,"end_date" text NOT NULL DEFAULT ''::text,"is_closed" boolean NOT NULL DEFAULT false,"closed_at" text,"notes" text,"opening_balance" bigint DEFAULT 0,"closing_balance" bigint,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (year));
CREATE TABLE public.loans("id" text NOT NULL,"title" text NOT NULL DEFAULT ''::text,"lender" text NOT NULL DEFAULT ''::text,"total_amount" bigint NOT NULL DEFAULT 0,"installment_amount" bigint NOT NULL DEFAULT 0,"total_installments" integer NOT NULL DEFAULT 0,"paid_installments" integer NOT NULL DEFAULT 0,"start_date" text NOT NULL DEFAULT ''::text,"next_due_date" text NOT NULL DEFAULT ''::text,"interest_rate" numeric,"notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (id));
CREATE TABLE public.members("id" text NOT NULL,"name" text NOT NULL DEFAULT ''::text,"share_percentage" numeric NOT NULL DEFAULT 0,"is_working_force" boolean NOT NULL DEFAULT false,"role" text NOT NULL DEFAULT ''::text,"phone" text,"iban" text,"national_id" text,"join_date" text NOT NULL DEFAULT ''::text,"notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (id));
CREATE TABLE public.salary_matrix("id" text NOT NULL,"employee_id" text NOT NULL,"year" integer NOT NULL,"month" integer NOT NULL,"amount" bigint NOT NULL DEFAULT 0,"bonus" bigint,"status" text NOT NULL DEFAULT 'paid'::text,"color_tag" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,CHECK (((month >= 1) AND (month <= 12))),PRIMARY KEY (id),CHECK ((status = ANY (ARRAY['paid'::text, 'pending'::text, 'zero'::text]))));
CREATE TABLE public.service_tariffs("id" text NOT NULL,"internal_code" text NOT NULL DEFAULT ''::text,"service_code" text NOT NULL DEFAULT ''::text,"title" text NOT NULL DEFAULT ''::text,"unit" text NOT NULL DEFAULT 'نوبت'::text,"current_price" bigint NOT NULL DEFAULT 0,"sub_category" text NOT NULL DEFAULT 'general'::text,"default_vat_rate" numeric NOT NULL DEFAULT 10,"price_history" jsonb NOT NULL DEFAULT '[]'::jsonb,"is_active" boolean NOT NULL DEFAULT true,"notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),PRIMARY KEY (id));
CREATE TABLE public.transactions("id" text NOT NULL,"type" text NOT NULL,"category" text NOT NULL,"sub_category" text,"amount" bigint NOT NULL DEFAULT 0,"year" integer NOT NULL,"month" integer NOT NULL,"day" integer NOT NULL,"date_string" text NOT NULL DEFAULT ''::text,"title" text NOT NULL DEFAULT ''::text,"description" text,"recipient_or_payer" text,"tracking_code" text,"related_member_id" text,"member_payout_type" text,"related_employee_id" text,"related_loan_id" text,"created_by" text,"created_by_name" text,"created_at" text,"updated_by" text,"updated_by_name" text,"updated_at" text,"db_created_at" timestamptz NOT NULL DEFAULT now(),"db_updated_at" timestamptz NOT NULL DEFAULT now(),CHECK (((day >= 1) AND (day <= 31))),CHECK (((month >= 1) AND (month <= 12))),PRIMARY KEY (id),CHECK ((type = ANY (ARRAY['income'::text, 'expense'::text]))));
CREATE TABLE public.vat_invoices("id" text NOT NULL,"invoice_number" text NOT NULL DEFAULT ''::text,"system_invoice_id" text,"invoice_type" text NOT NULL DEFAULT 'نوع دوم'::text,"invoice_pattern" text NOT NULL DEFAULT 'فروش'::text,"invoice_subject" text NOT NULL DEFAULT 'اصلی'::text,"period_type" text NOT NULL DEFAULT 'seasonal'::text,"season" text,"month" integer,"year" integer NOT NULL,"issue_date_time" text NOT NULL DEFAULT ''::text,"seller_economic_code" text NOT NULL DEFAULT ''::text,"seller_national_id" text NOT NULL DEFAULT ''::text,"seller_company_name" text NOT NULL DEFAULT ''::text,"seller_person_name" text NOT NULL DEFAULT ''::text,"seller_postal_code" text NOT NULL DEFAULT ''::text,"seller_branch_code" text,"buyer_title" text,"buyer_economic_code" text,"buyer_national_id" text,"buyer_person_name" text,"buyer_postal_code" text,"buyer_branch_code" text,"items" jsonb NOT NULL DEFAULT '[]'::jsonb,"total_quantity" integer NOT NULL DEFAULT 0,"total_gross_amount" bigint NOT NULL DEFAULT 0,"total_discount" bigint NOT NULL DEFAULT 0,"total_vat_amount" bigint NOT NULL DEFAULT 0,"article17_tax" bigint NOT NULL DEFAULT 0,"final_amount" bigint NOT NULL DEFAULT 0,"amount_in_words" text,"is_synced_to_transactions" boolean NOT NULL DEFAULT false,"synced_transaction_id" text,"synced_transaction_ids" jsonb,"monthly_allocation" jsonb,"is_synthesized_from_monthly" boolean DEFAULT false,"synthesized_from_invoice_ids" jsonb,"notes" text,"created_at" text NOT NULL DEFAULT ''::text,"updated_at" text,"db_created_at" timestamptz NOT NULL DEFAULT now(),"db_updated_at" timestamptz NOT NULL DEFAULT now(),CHECK ((period_type = ANY (ARRAY['seasonal'::text, 'monthly'::text]))),PRIMARY KEY (id));
